#include <stdio.h>
#include <stdlib.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

static inline long long max(long long a, long long b) {
    return (a > b) ? a : b;
}

int main(void) {
    int n, k, c;
    if (scanf("%d %d %d", &n, &k, &c) != 3) {
        return 0;
    }

    long long *a = (long long *)malloc((n + 1) * sizeof(long long));
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
    }

    long long *prev_dp = (long long *)malloc((n + 1) * sizeof(long long));
    long long *curr_dp = (long long *)malloc((n + 1) * sizeof(long long));

    prev_dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        prev_dp[i] = prev_dp[i - 1] + a[i];
    }

    for (int j = 1; j <= k; j++) {
        int start = j * c;
        for (int i = 0; i < start && i <= n; i++) {
            curr_dp[i] = -INF;
        }

        for (int i = start; i <= n; i++) {
            long long not_covered = curr_dp[i - 1] + a[i];
            long long covered = prev_dp[i - c];
            curr_dp[i] = max(not_covered, covered);
        }

        for (int i = 0; i <= n; i++) {
            prev_dp[i] = curr_dp[i];
        }
    }

    printf("%lld\n", prev_dp[n]);

    free(a);
    free(prev_dp);
    free(curr_dp);

    return 0;
}
